.version 7.2
.target sm_80
.address_size 64

.visible .entry groupnorm_kernel (
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 channels,
    .param .u32 height,
    .param .u32 width,
    .param .u32 groups
)
{
    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    .reg .u64 %input, %output;
    .reg .u32 %N, %C, %H, %W, %G;
    ld.param.u64 %input, [input_ptr];
    ld.param.u64 %output, [output_ptr];
    ld.param.u32 %N, [batch];
    ld.param.u32 %C, [channels];
    ld.param.u32 %H, [height];
    ld.param.u32 %W, [width];
    ld.param.u32 %G, [groups];

    // -------------------------------------------------
    // Compute per‑block indices: each block handles one (n, g)
    // -------------------------------------------------
    .reg .u32 %blockIdx;
    mov.u32 %blockIdx, %ctaid.x;                 // linear block id = n*G + g

    .reg .u32 %n_idx, %g_idx, %tmp;
    div.u32 %n_idx, %blockIdx, %G;               // n = blockIdx / G
    mul.lo.u32 %tmp, %n_idx, %G;
    sub.u32 %g_idx, %blockIdx, %tmp;             // g = blockIdx % G

    // -------------------------------------------------
    // Compute derived sizes
    // -------------------------------------------------
    .reg .u32 %C_per_g;
    div.u32 %C_per_g, %C, %G;                     // channels per group

    .reg .u64 %group_elem;
    cvt.u64.u32 %group_elem, %C_per_g;
    mul.lo.u64 %group_elem, %group_elem, %H;
    mul.lo.u64 %group_elem, %group_elem, %W;     // elements per (n,g) group

    // -------------------------------------------------
    // Compute starting offset of this group in the flat tensor
    // -------------------------------------------------
    .reg .u64 %offset_n, %offset_g, %offset;
    // offset_n = n * C * H * W
    cvt.u64.u32 %tmp, %n_idx;
    cvt.u64.u32 %tmp, %C;
    mul.lo.u64 %offset_n, %tmp, %H;
    mul.lo.u64 %offset_n, %offset_n, %W;
    // offset_g = g * C_per_g * H * W
    cvt.u64.u32 %tmp, %g_idx;
    cvt.u64.u32 %tmp, %C_per_g;
    mul.lo.u64 %offset_g, %tmp, %H;
    mul.lo.u64 %offset_g, %offset_g, %W;
    // total offset
    add.u64 %offset, %offset_n, %offset_g;

    // Pointers to this group's data
    add.u64 %input, %input, %offset;
    add.u64 %output, %output, %offset;

    // -------------------------------------------------
    // Thread‑wise reduction to compute sum and sumsq (fp32)
    // -------------------------------------------------
    .reg .u32 %tid;
    mov.u32 %tid, %tid.x;

    .reg .u64 %stride, %i;
    mov.u64 %stride, 1024;                       // blockDim.x
    cvt.u64.u32 %i, %tid;

    .reg .f32 %sum, %sumsq, %val_f32, %tmp_f32;
    mov.f32 %sum, 0f0;
    mov.f32 %sumsq, 0f0;

LOOP_SUM:
    setp.ge.u64 %p_done, %i, %group_elem;
    @%p_done bra END_SUM;
    // load fp16 element
    .reg .f16 %val_f16;
    ld.global.b16 %val_f16, [%input + %i*2];
    // convert to fp32
    cvt.f32.f16 %val_f32, %val_f16;
    // accumulate
    add.f32 %sum, %sum, %val_f32;
    mul.f32 %tmp_f32, %val_f32, %val_f32;
    add.f32 %sumsq, %sumsq, %tmp_f32;
    // i += stride
    add.u64 %i, %i, %stride;
    bra LOOP_SUM;
END_SUM:

    // -------------------------------------------------
    // Block‑level reduction (shared memory)
    // -------------------------------------------------
    .shared .align 4 .f32 sh_sum[1024];
    .shared .align 4 .f32 sh_sumsq[1024];
    st.shared.f32 [sh_sum+%tid*4], %sum;
    st.shared.f32 [sh_sumsq+%tid*4], %sumsq;
    bar.sync 0;

    // reduction tree
    .reg .u32 %offset_red;
    mov.u32 %offset_red, 512;
REDU_LOOP:
    setp.ge.u32 %p_skip, %tid, %offset_red;
    @%p_skip bra SKIP_REDU;
    ld.shared.f32 %tmp_f32, [sh_sum+%tid*4];
    ld.shared.f32 %tmp_f32, [sh_sum+(%tid+%offset_red)*4];
    add.f32 %tmp_f32, %tmp_f32, %tmp_f32;
    st.shared.f32 [sh_sum+%tid*4], %tmp_f32;

    ld.shared.f32 %tmp_f32, [sh_sumsq+%tid*4];
    ld.shared.f32 %tmp_f32, [sh_sumsq+(%tid+%offset_red)*4];
    add.f32 %tmp_f32, %tmp_f32, %tmp_f32;
    st.shared.f32 [sh_sumsq+%tid*4], %tmp_f32;
SKIP_REDU:
    bar.sync 0;
    shr.u32 %offset_red, %offset_red, 1;
    setp.ne.u32 %p_cont, %offset_red, 0;
    @%p_cont bra REDU_LOOP;

    // -------------------------------------------------
    // Compute mean and inv_std (thread 0)
    // -------------------------------------------------
    .reg .f32 %mean, %var, %inv_std, %eps;
    mov.f32 %eps, 0f3c23d70a;                     // 1e-5

    setp.eq.u32 %p0, %tid, 0;
    @%p0 {
        ld.shared.f32 %sum, [sh_sum];
        ld.shared.f32 %sumsq, [sh_sumsq];
        // mean = sum / N
        cvt.f32.u64 %tmp_f32, %group_elem;
        div.f32 %mean, %sum, %tmp_f32;
        // var = (sumsq / N) - mean*mean
        div.f32 %var, %sumsq, %tmp_f32;
        mul.f32 %tmp_f32, %mean, %mean;
        sub.f32 %var, %var, %tmp_f32;
        add.f32 %var, %var, %eps;
        rsqrt.approx.f32 %inv_std, %var;
        // store for broadcast
        st.shared.f32 [sh_sum], %mean;          // reuse sh_sum[0] as mean
        st.shared.f32 [sh_sumsq], %inv_std;     // reuse sh_sumsq[0] as inv_std
    }
    bar.sync 0;
    ld.shared.f32 %mean, [sh_sum];
    ld.shared.f32 %inv_std, [sh_sumsq];

    // -------------------------------------------------
    // Second pass: normalize and write output
    // -------------------------------------------------
    mov.u64 %i, %tid;                            // reset i = threadIdx
LOOP_NORM:
    setp.ge.u64 %p_done2, %i, %group_elem;
    @%p_done2 bra END_NORM;
    ld.global.b16 %val_f16, [%input + %i*2];
    cvt.f32.f16 %val_f32, %val_f16;
    sub.f32 %val_f32, %val_f32, %mean;
    mul.f32 %val_f32, %val_f32, %inv_std;
    cvt.f16.f32 %val_f16, %val_f32;
    st.global.b16 [%output + %i*2], %val_f16;
    add.u64 %i, %i, %stride;
    bra LOOP_NORM;
END_NORM:

    ret;
}
'''

class ModelNew:
    def __init__(self, features, num_groups):
        self.features = features
        self.num_groups = num_groups

    def __call__(self, x):
        import torch
        # allocate output tensor
        out = torch.empty_like(x)
        # launch parameters
        batch, C, H, W = x.shape
        grid = (batch * self.num_groups, )       # one block per (n,g)
        block = (1024, )                         # 1024 threads per block
        args = [
            x.data_ptr(),
            out.data_ptr(),
            batch,
            C,
            H,
            W,
            self.num_groups
        ]
        module = ptx_load(PTX_SOURCE)
        ptx_launch(module, "groupnorm_kernel", grid, block, args)
        return out
